void renderTree(){if(tree==null)return;tree.removeAllViews();for(String p:files.keySet()){TextView t=label((p.endsWith(".java")?"◇  ":p.endsWith(".xml")?"⌘  ":"▤  ")+p,10,p.equals(active)?BL:TX);t.setPadding(dp(3+p.split("/").length*4),dp(7),dp(2),dp(7));if(p.equals(active))t.setBackground(shape(P2,0));tree.addView(t);t.setOnClickListener(v->{saveLocal();active=p;loadFile(p);renderTree();});}}
void loadFile(String p){if(fileTitle!=null)fileTitle.setText("  "+p);if(editor!=null)editor.setText(files.getOrDefault(p,""));}void saveLocal(){if(ready&&editor!=null&&!active.isEmpty())files.put(active,editor.getText().toString());}
void newFile(){EditText e=new EditText(this);e.setSingleLine(true);e.setHint("app/src/main/java/Example.java");new AlertDialog.Builder(this).setTitle("New file").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Create",(d,w)->{String p=e.getText().toString().trim();if(p.isEmpty()||p.startsWith("/")||Arrays.asList(p.split("/")).contains("..")||files.containsKey(p)){toast("Invalid or existing path");return;}saveLocal();files.put(p,"");active=p;renderTree();loadFile(p);saveRemote();}).show();}
void aiSettings(){LinearLayout box=col();box.setPadding(dp(8),0,dp(8),0);box.addView(label("AI provider settings. You can leave these blank and configure them later. Compatible with OpenAI-style APIs.",12,MU));EditText base=new EditText(this);base.setSingleLine(true);base.setHint("BASE URL (e.g. https://api.openai.com/v1)");base.setText(sec.getString("ai_base_url","https://api.openai.com/v1"));box.addView(base);EditText key=new EditText(this);key.setSingleLine(true);key.setHint("API KEY");key.setInputType(129);key.setText(sec.getString("openai_key",""));box.addView(key);EditText model=new EditText(this);model.setSingleLine(true);model.setHint("MODEL ID (e.g. gpt-4o-mini)");model.setText(sec.getString("ai_model_id","gpt-4o-mini"));box.addView(model);new AlertDialog.Builder(this).setTitle("AI settings").setView(box).setNegativeButton("Cancel",null).setNeutralButton("GitHub token",(d,w)->setup()).setPositiveButton("Save",(d,w)->{String u=base.getText().toString().trim(),k=key.getText().toString().trim(),m=model.getText().toString().trim();if(u.isEmpty())u="https://api.openai.com/v1";if(m.isEmpty())m="gpt-4o-mini";if(!u.startsWith("https://")&&!u.startsWith("http://")){toast("BASE URL must start with https:// or http://");return;}sec.edit().putString("ai_base_url",u).putString("openai_key",k).putString("ai_model_id",m).apply();toast("AI settings saved");}).show();}
void addMsg(String who,String s,boolean user){TextView t=label(who+"\n"+s,11,user?TX:MU);t.setPadding(dp(7),dp(6),dp(7),dp(6));t.setBackground(shape(user?Color.rgb(34,48,70):P2,BD));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(3),0,dp(3));chat.addView(t,p);}
void askAI(){String q=prompt.getText().toString().trim(),key=sec.getString("openai_key","");if(q.isEmpty())return;if(key.isEmpty()){setup();toast("Add OpenAI API key for AI");return;}saveLocal();prompt.setText("");addMsg("You",q,true);JSONArray ctx=new JSONArray();try{for(Map.Entry<String,String> e:files.entrySet()){JSONObject f=new JSONObject();f.put("path",e.getKey());f.put("content",e.getValue());ctx.put(f);}}catch(Exception ignored){}String ins="You are DevStudio Android coding agent. Return a JSON object with fields reply and actions. Each action has type write_file, path, and content. Think means no edits. Never use absolute paths or .. segments. Project files: "+ctx+" User request: "+q;ex.execute(()->{String out=aiCall(key,ins);runOnUiThread(()->{if(out==null){addMsg("AI","Check OpenAI key, internet and billing.",false);return;}try{JSONObject j=new JSONObject(out);JSONArray a=j.optJSONArray("actions");if(a!=null)for(int i=0;i<a.length();i++){JSONObject x=a.getJSONObject(i);String p=x.optString("path","");if("write_file".equals(x.optString("type"))&&!p.isEmpty()&&!p.startsWith("/")&&!Arrays.asList(p.split("/")).contains(".."))files.put(p,x.optString("content",""));}renderTree();loadFile(active);addMsg("DevStudio AI",j.optString("reply","Done.")+" Save changed files to commit them.",false);status.setText("  ● AI done · check files");}catch(Exception e){addMsg("AI",out,false);}});});}
String aiCall(String key,String q){HttpURLConnection c=null;try{String base=sec.getString("ai_base_url","https://api.openai.com/v1").trim().replaceAll("/+$","");if(!base.endsWith("/v1")&&!base.endsWith("/v1beta/openai"))base=base+"/v1";String endpoint=base+"/chat/completions";c=(HttpURLConnection)new URL(endpoint).openConnection();c.setRequestMethod("POST");c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+key);c.setRequestProperty("Content-Type","application/json");JSONObject b=new JSONObject();b.put("model",sec.getString("ai_model_id","gpt-4o-mini"));JSONArray a=new JSONArray();JSONObject m=new JSONObject();m.put("role","user");m.put("content",q);a.put(m);b.put("messages",a);try(OutputStream o=c.getOutputStream()){o.write(b.toString().getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()>=400)return null;return new JSONObject(new String(c.getInputStream().readAllBytes(),StandardCharsets.UTF_8)).getJSONArray("choices").getJSONObject(0).getJSONObject("message").getString("content");}catch(Exception e){return null;}finally{if(c!=null)c.disconnect();}}
void saveRemote(){if(repo.isEmpty()){try{saveLocal();saveLocalFiles();status.setText("  ● Saved locally on phone");toast("Saved locally");}catch(Exception e){err("Local save failed",e.getMessage());}return;}saveLocal();String p=active,c=files.getOrDefault(active,"");status.setText("  Saving to GitHub…");ex.execute(()->{try{String token=sec.getString("github_token","");JSONObject old=null;try{old=api(token,"GET","/repos/"+repo+"/contents/"+pathEnc(p)+"?ref="+enc(branch),null);}catch(Exception ignored){}JSONObject b=new JSONObject();b.put("message","DevStudio: update "+p);b.put("content",Base64.getEncoder().encodeToString(c.getBytes(StandardCharsets.UTF_8)));b.put("branch",branch);if(old!=null&&old.has("sha"))b.put("sha",old.getString("sha"));api(token,"PUT","/repos/"+repo+"/contents/"+pathEnc(p),b);runOnUiThread(()->{status.setText("  ● Saved to GitHub: "+p);toast("Committed "+p);});}catch(Exception e){runOnUiThread(()->err("Save failed",e.getMessage()));}});}
void buildRemote(){if(repo.isEmpty()){buildLocalWithLog();return;}ex.execute(()->{try{JSONObject b=new JSONObject();b.put("ref",branch);api(sec.getString("github_token",""),"POST","/repos/"+repo+"/actions/workflows/build-apk.yml/dispatches",b);runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Build started").setMessage("GitHub Actions is building this project. Save edits first, then open Actions to download the APK artifact.").setPositiveButton("Open Actions",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/"+repo+"/actions")))).setNegativeButton("Close",null).show());}catch(Exception e){runOnUiThread(()->err("Build failed",e.getMessage()+" Token needs Actions: write permission."));}});}
void appendBuildLog(TextView out,ScrollView scroll,String line){runOnUiThread(()->{out.append(line+"\n");scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));});}
void buildLocalWithLog(){if(localProjectName.isEmpty()){toast("Open or create a local project first");return;}LinearLayout box=col();box.setPadding(dp(8),dp(4),dp(8),dp(4));TextView summary=label("Local Gradle build · live output",12,GR);box.addView(summary);ScrollView scroll=new ScrollView(this);TextView output=label("Preparing local build…\n",11,TX);output.setTypeface(Typeface.MONOSPACE);output.setTextIsSelectable(true);output.setPadding(dp(8),dp(8),dp(8),dp(8));output.setBackground(shape(P,BD));scroll.addView(output,new ScrollView.LayoutParams(-1,-2));box.addView(scroll,new LinearLayout.LayoutParams(-1,dp(300)));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Build Log").setView(box).setPositiveButton("Close",null).create();dialog.show();dialog.getWindow().setLayout(Math.min(getResources().getDisplayMetrics().widthPixels-dp(32),dp(700)),-2);ex.execute(()->{try{saveLocalFiles();File base=new File(getFilesDir(),"projects/"+localProjectName);appendBuildLog(output,scroll,"[DevStudio] Project: "+base.getAbsolutePath());downloadGradleWrapper(base,output,scroll);String javaHome=System.getenv("JAVA_HOME"),androidHome=System.getenv("ANDROID_HOME");appendBuildLog(output,scroll,"[Gradle] Wrapper downloaded. Distribution: Gradle 8.9");appendBuildLog(output,scroll,"[Environment] JAVA_HOME="+(javaHome==null?"not set":javaHome));appendBuildLog(output,scroll,"[Environment] ANDROID_HOME="+(androidHome==null?"not set":androidHome));File script=new File(base,"gradlew");ProcessBuilder pb=new ProcessBuilder("/system/bin/sh",script.getAbsolutePath(),"--no-daemon","assembleDebug");pb.directory(base);pb.redirectErrorStream(true);if(androidHome!=null)pb.environment().put("ANDROID_HOME",androidHome);java.lang.Process process=pb.start();try(BufferedReader reader=new BufferedReader(new InputStreamReader(process.getInputStream(),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null)appendBuildLog(output,scroll,line);}int code=process.waitFor();appendBuildLog(output,scroll,"[Gradle] Exit code: "+code);if(code==0)appendBuildLog(output,scroll,"[SUCCESS] APK: app/build/outputs/apk/debug/app-debug.apk");else appendBuildLog(output,scroll,"[BUILD FAILED] Check missing Java runtime or Android SDK above.");}catch(Exception e){appendBuildLog(output,scroll,"[ERROR] "+e.getClass().getSimpleName()+": "+e.getMessage());appendBuildLog(output,scroll,"[INFO] Wrapper files are saved locally. Android builds also require a working Java runtime and Android SDK on the phone.");}});}
void downloadGradleWrapper(File base,TextView output,ScrollView scroll)throws Exception{File dir=new File(base,"gradle/wrapper");if(!dir.exists()&&!dir.mkdirs())throw new IOException("Cannot create gradle/wrapper");downloadIfMissing("https://raw.githubusercontent.com/gradle/gradle/v8.9.0/gradlew",new File(base,"gradlew"),output,scroll);downloadIfMissing("https://raw.githubusercontent.com/gradle/gradle/v8.9.0/gradlew.bat",new File(base,"gradlew.bat"),output,scroll);downloadIfMissing("https://raw.githubusercontent.com/gradle/gradle/v8.9.0/gradle/wrapper/gradle-wrapper.properties",new File(dir,"gradle-wrapper.properties"),output,scroll);downloadIfMissing("https://raw.githubusercontent.com/gradle/gradle/v8.9.0/gradle/wrapper/gradle-wrapper.jar",new File(dir,"gradle-wrapper.jar"),output,scroll);File props=new File(dir,"gradle-wrapper.properties");try(FileOutputStream o=new FileOutputStream(props)){o.write("distributionBase=GRADLE_USER_HOME\n distributionPath=wrapper/dists\n distributionUrl=https\\://services.gradle.org/distributions/gradle-8.9-bin.zip\nzipStoreBase=GRADLE_USER_HOME\nzipStorePath=wrapper/dists\n".replace("\n ","\n").getBytes(StandardCharsets.UTF_8));}new ProcessBuilder("/system/bin/chmod","755",new File(base,"gradlew").getAbsolutePath()).start().waitFor();}
void downloadIfMissing(String url,File target,TextView output,ScrollView scroll)throws Exception{if(target.isFile()&&target.length()>0){appendBuildLog(output,scroll,"[Cache] "+target.getName()+" already downloaded");return;}appendBuildLog(output,scroll,"[Download] "+target.getName());HttpURLConnection con=(HttpURLConnection)new URL(url).openConnection();con.setConnectTimeout(20000);con.setReadTimeout(60000);con.setRequestProperty("User-Agent","DevStudio-Android");try{int code=con.getResponseCode();if(code<200||code>=300)throw new IOException("HTTP "+code+" downloading "+target.getName());try(InputStream in=con.getInputStream();FileOutputStream out=new FileOutputStream(target)){byte[] buf=new byte[16384];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}if(target.length()==0)throw new IOException("Downloaded empty file: "+target.getName());appendBuildLog(output,scroll,"[OK] "+target.getName()+" ("+target.length()+" bytes)");}finally{con.disconnect();}}
